{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 쿼리의 병목을 분석한 근거와 개선 전후 측정 내용을 통해, 원인에 맞는 개선 방법을 적용하고 성능 향상을 수치로 검증할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "신고 목록 조회가 느렸던 상황과 당시 조회 조건, 데이터 규모 등 성능 측정에 영향을 주는 조건을 설명한다.",
          "task": "본인이 담당한 쿼리 개선 범위와 개선 효과를 확인해야 했던 대상을 설명한다.",
          "action": "실행 계획이나 로그에서 병목을 확인한 근거, 인덱스 추가와 조인 정리를 선택한 이유, 개선 전후를 비교한 측정 방법을 설명한다.",
          "result": "3.2초에서 0.4초로 줄어든 측정 결과와 비교 조건을 제시하고, 해당 결과가 병목 개선의 효과임을 확인한 근거를 설명한다."
        },
        "expectedEvidence": [
          "실행 계획, 로그 또는 호출 구조에서 확인한 구체적인 병목 징후",
          "확인한 병목과 인덱스 추가·조인 정리 사이의 인과관계",
          "개선 전후의 조회 조건과 측정 환경을 비교 가능하게 맞춘 방법",
          "개선 전후 응답 시간의 수치와 그 수치를 확인한 측정 근거"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 3.2초에서 0.4초로 단축했을 때, 성능 개선의 효과를 검증한 방법은 무엇이었나요?",
      "answerTip": "직접 수행한 사례를 중심으로 핵심 내용을 차분하게 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획이나 로그에서 확인한 병목을 구체적으로 설명하고, 인덱스 추가와 조인 정리가 해당 병목을 줄이는 이유를 연결한다.",
            "개선 전후의 조회 조건과 측정 환경을 비교 가능하게 맞춘 방법을 설명한다.",
            "3.2초와 0.4초의 측정 근거를 제시하며, 수치 변화가 개선 효과임을 확인한 방법을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "병목에 대한 확인 근거와 적용한 개선 방법의 관련성은 설명하지만, 실행 계획이나 로그의 구체적인 내용이 부족하다.",
            "개선 전후 응답 시간과 측정 방법은 제시하지만, 비교 조건을 맞춘 방법이나 결과 검증에 대한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스 추가나 조인 정리를 했다는 사실만 제시하고, 어떤 병목을 근거로 선택했는지 설명하지 못한다.",
            "개선 수치만 반복하거나 체감상 빨라졌다고 설명하며, 측정 방법과 비교 근거를 제시하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 알림 중복 발송 오류를 로그와 지표로 추적해 원인을 좁히고, 당장의 복구와 재발 방지 조치를 구분하여 수행할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배포 후 알림 중복 발송 문의가 발생했던 상황과 오류가 드러난 양상을 설명한다.",
          "task": "본인이 맡은 오류 조사와 수정 범위, 중복 발송을 해소하기 위해 확인해야 했던 대상을 설명한다.",
          "action": "로그의 시간과 서버별 실행 내역, 중복 발생 지표 등을 대조해 원인을 좁힌 순서를 설명하고, 복구 조치와 재발 방지 조치를 구분한다.",
          "result": "조치 후 중복 발송이 해소되었는지 로그나 지표로 확인한 결과와 동일 장애의 재발을 방지하기 위해 반영한 내용을 설명한다."
        },
        "expectedEvidence": [
          "오류 발생 시점과 서버별 실행 내역을 연결한 로그 추적 근거",
          "로그와 중복 발생 지표 등을 통해 스케줄러 중복 실행으로 원인을 좁힌 과정",
          "당장의 중복 발송 해소를 위한 복구 조치와 적용 이유",
          "복구 조치와 구분되는 재발 방지 방안 및 확인 절차",
          "조치 후 중복 발송 해소 여부를 확인한 로그나 지표"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 로그로 추적했을 때, 장애를 해결하기 위해 적용한 대응 순서는 무엇이었나요?",
      "answerTip": "당시 본인이 수행한 내용을 시간 흐름에 따라 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "시간순 로그와 서버별 실행 내역, 중복 발생 지표를 연결하여 스케줄러 중복 실행으로 원인을 좁힌 과정을 구체적으로 설명한다.",
            "당장의 중복 발송을 해소한 조치와 동일 장애의 재발을 막는 조치를 목적에 따라 구분하여 설명한다.",
            "조치 후 로그나 지표로 중복 발송 해소 여부를 확인한 결과와 재발 방지를 위한 확인 절차를 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그로 스케줄러 중복 실행을 확인한 근거와 복구 조치는 설명하지만, 원인을 좁힌 과정이나 지표 활용이 구체적이지 않다.",
            "재발 방지 방안을 제시하지만, 복구 조치와의 구분 또는 조치 후 효과를 확인한 근거가 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "스케줄러가 원인이었다는 결론만 말하고, 로그나 지표로 원인을 추적한 근거를 설명하지 못한다.",
            "수정했다는 설명에 그치며, 복구 조치와 재발 방지 방안 또는 중복 발송 해소 여부를 확인한 근거를 제시하지 못한다."
          ]
        }
      }
    }
  ]
}
